from dataclasses import dataclass
from typing import Optional, Dict, List

@dataclass
class OrderResult:
    order_id: str
    total: float
    user_id: str

def validate_order(order: Optional[Dict]) -> bool:
    if order is None:
        return False
    if order.get('status') != 'pending':
        return False
    if not order.get('items', []):
        return False
    return order.get('user_id') is not None

def validate_items(items: List[Dict]) -> bool:
    for item in items:
        if item.get('price') is None or item.get('quantity') is None:
            return False
    return True

def process_order(order: Optional[Dict]) -> Optional[OrderResult]:
    if not validate_order(order):
        return None
    if not validate_items(order['items']):
        return None

    total = sum(item['price'] * item['quantity'] for item in order['items'])
    return OrderResult(
        order_id=order['id'],
        total=total,
        user_id=order['user_id']
    )
